const D = { energy: .6, scale: 1, speed: 1, density: .5, rough: .5, hue: 30, x: .5, y: .5, style: 'sem', seed: 0, alpha: 100 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

// ---- A fatigue fracture surface under the microscope. A crack initiates at a corner flaw and
// creeps: every load block leaves a BEACH MARK (arrest line), every cycle leaves a STRIATION, and
// striation spacing widens outward exactly as da/dN does (Paris law). Whatever the crack has not
// eaten is the FINAL OVERLOAD zone: microvoid-coalescence dimples. Ratchet marks step between
// initiation sites.
// The image IS the ordered concentric banding, so it is carried by TWO channels: a relief height
// field (normals -> raking light) AND an albedo field (the polished striated fan reads bright and
// banded, the matte dimpled overload reads dark) — the structure therefore survives any light
// angle instead of dissolving into shading noise. Roughness is deliberately LOW-FREQUENCY value
// noise: white per-pixel noise dominates the gradient and turns the whole plate to mush.
const cl = (v,a,b) => v<a?a:(v>b?b:v);
const BW = 176, BH = Math.max(76, Math.round(BW*height/Math.max(1,width)));
const N = BW*BH;
