  S.g = createGraphics(BW, BH); S.g.pixelDensity(1); S.bw = BW; S.bh = BH;
  S.H = new Float32Array(N); S.TN = new Float32Array(N);
}
const sd = P.seed|0;
function hsh(ix, iy, iz) {
  let h = (Math.imul(ix|0, 374761393) + Math.imul(iy|0, 668265263) + Math.imul(iz|0, 1274126177) + Math.imul(sd, 1442695041))|0;
  h = Math.imul(h ^ (h >>> 13), 1274126177)|0;
  return ((h ^ (h >>> 16)) >>> 0)/4294967295;
}
// smooth value noise — texture that does NOT swamp the relief gradient
function vn(x, y, z, cell) {
  const gx = x/cell, gy = y/cell;
  const i0 = Math.floor(gx), j0 = Math.floor(gy);
  let fx = gx - i0, fy = gy - j0;
  fx = fx*fx*(3 - 2*fx); fy = fy*fy*(3 - 2*fy);
  const a = hsh(i0, j0, z), b = hsh(i0+1, j0, z), c = hsh(i0, j0+1, z), d = hsh(i0+1, j0+1, z);
  const u1 = a + (b-a)*fx, u2 = c + (d-c)*fx;
  return u1 + (u2-u1)*fy;
}

// ---- monotonic internal clock (tolerates t0 resets) ----
if (S.lastT == null || K.t < S.lastT) S.lastT = K.t;
let dtc = K.t - S.lastT; S.lastT = K.t;
if (!(dtc >= 0) || dtc > .25) dtc = 1/60;
S.tt = (S.tt || 0) + dtc;
const tt = S.tt, style = P.style;
const zoom = Math.max(1, P.scale);

// ---- specimen life: ~96s, then a slow low-frequency re-etch onto a fresh specimen ----
const life = tt*(P.speed/96);
const spec = Math.floor(life);
const cyc = life - spec;
const diss = Math.max(0, (cyc - .88)/.12);          // ~11s at speed 1 — never a cut, never a flash

// per-specimen constants (frozen for the whole life — a fracture surface is a RECORD; if it
// re-animates it stops reading as a thing that happened)
function specimen(id) {
  const q = id*977;
  const cornerA = hsh(q, 1, 5)*6.2831;
  return {
    ox: .5 + .42*Math.cos(cornerA),               // origin sits at a stress concentrator on the edge
    oy: .5 + .42*Math.sin(cornerA),
    p1: hsh(q,2,5)*6.2831, p2: hsh(q,3,5)*6.2831, p3: hsh(q,4,5)*6.2831,
    a1: .16 + .22*hsh(q,5,5), a2: .08 + .14*hsh(q,6,5),
    nr: 2 + Math.floor(hsh(q,7,5)*3),             // ratchet mark count
    r1: hsh(q,8,5)*6.2831, r2: hsh(q,9,5)*6.2831, r3: hsh(q,10,5)*6.2831,
    nb: 5 + Math.floor(hsh(q,11,5)*7)             // load blocks -> beach marks
  };
}
