// striation law: spacing s(u) = s0*(1+k*u)  ->  phase(u) = ln(1+k*u)/(s0*k).
// s0 is set so the fringes resolve to 3-4 buffer px at mid-radius: the first cut ran them at
// ~1.9px, i.e. straight into Nyquist, which is why no striations were visible at all.
const s0 = .010*(1.5 - .9*cl(P.density,0,1));
const kk = 3.2;
const invs = 1/(s0*kk);
const HB = S.H, TB = S.TN;
const pu = 1/(BH*zoom);                            // one buffer pixel, in specimen units
const BSC = 1/pu;                                  // buffer px per specimen unit
const RG = cl(P.rough,0,1);
const cs = 3.0 + RG*2.6;                           // dimple cell size, buffer px

let OH = 0, OT = 0;
function surf(sx, sy, SP, aa) {
  const dx = sx - SP.ox, dy = sy - SP.oy;
  const r = Math.sqrt(dx*dx + dy*dy);
  const th = Math.atan2(dy, dx);
  // the crack front is not a circle: it runs faster in some directions
  const R = 1 + SP.a1*Math.sin(th*2 + SP.p1) + SP.a2*Math.sin(th*3 + SP.p2) + .07*Math.sin(th*5 + SP.p3);
  const uu = r/Math.max(.25, R);
  // the fatigue/overload boundary is ragged, but smoothly so (continuous in theta)
  const tj = th*7, tj0 = Math.floor(tj);
  let tf = tj - tj0; tf = tf*tf*(3 - 2*tf);
  const h0 = hsh(tj0, 0, 13), h1 = hsh(tj0+1, 0, 13);
  const front = aa + ((h0 + (h1-h0)*tf) - .5)*.07;
  const gx = sx*BSC, gy = sy*BSC;
  if (uu > front) {
    // ---- final overload: microvoid coalescence dimples (matte, dark, subordinate) ----
    const ci = Math.floor(gx/cs), cj = Math.floor(gy/cs);
    let f1 = 1e9;
    for (let jj = cj-1; jj <= cj+1; jj++) for (let ii = ci-1; ii <= ci+1; ii++) {
      const px = (ii + hsh(ii, jj, 21))*cs, py = (jj + hsh(ii, jj, 22))*cs;
      const ddx = gx - px, ddy = gy - py; const d = ddx*ddx + ddy*ddy;
      if (d < f1) f1 = d;
    }
    const d1 = Math.min(1, Math.sqrt(f1)/(cs*.72));
    OH = -.34*(1-d1)*(1-d1)*(.45 + .55*RG) + .10;        // each void is a cup
    OH += (vn(gx, gy, 23, 5.5) - .5)*.030*RG;
    OT = .40 + .11*d1;                                    // matte
    const tr = Math.max(0, 1 - (uu - front)*22);          // bright shear lip at the transition
    OH += tr*.16; OT += tr*.30;
  } else {
    // ---- fatigue zone: striations + beach marks, both ordered and rhythmic ----
    const phi = Math.log(1 + kk*uu)*invs;
    const dphidu = 1/(s0*(1 + kk*uu));
    const al = dphidu*pu/.30;                             // anti-alias the sub-pixel inner rings
    const fade = 1/(1 + al*al);
    const str = Math.cos(phi*6.2831)*.030*fade;
    // BEACH MARKS — the image. Each load block leaves a shallow CLAMSHELL: the surface arches
    // across the block and creases into a groove at the arrest line. Spacing widens outward with
    // uu^0.72 because the growth rate does. The arch is the dominant relief in the fatigue zone
    // by an order of magnitude over the striations, so the raking light bands the fan into
    // ordered concentric shells instead of shading noise.
    const bp = SP.nb*Math.pow(uu > .02 ? uu : .02, .72) + .18*Math.sin(uu*7.3 + SP.p1);
    let bm = .5 + .5*Math.cos(bp*6.2831); bm = bm*bm; bm = bm*bm;   // ^4 — the narrow arrest crease
    const blk = Math.floor(bp);
    const arch = Math.sin(3.14159*(bp - blk));           // one shell per load block
    const stp = blk - 2*Math.floor(blk*.5);              // load-block parity -> tonal step
    // ratchet marks: radial steps where separate initiation sites joined up
    let rat = 0;
    const rs = SP.nr > 2 ? [SP.r1, SP.r2, SP.r3] : [SP.r1, SP.r2];
    for (let k = 0; k < SP.nr && k < rs.length; k++) {
      let dth = th - rs[k]; while (dth > 3.1416) dth -= 6.2831; while (dth < -3.1416) dth += 6.2831;
      rat += .075*Math.exp(-(dth*dth)/.0022)*Math.exp(-uu*2.6);
    }
    OH = .10 + arch*.24 - bm*.09 + str + rat + (vn(gx, gy, 31, 6) - .5)*.016*(.4 + RG);
    // ALBEDO: the striated fan is polished and bright, each arrest line is a dark rule, and
    // consecutive load blocks step in tone. The concentric structure therefore reads in TONE as
    // well as in relief — it cannot dissolve into the shading whatever the light does.
    OT = .70 + stp*.07 - bm*.30 + .10*(1 - Math.min(1, uu)) + str*1.2 + rat*.8;
  }
}

// ---- pass 1: height + albedo ----
const aA = .12 + Math.pow(cyc, 1.7)*1.45;                 // this specimen's crack length
const aB = .12;                                            // the next one, fresh
const halfAsp = (BH/BW)*.5;
for (let j = 0; j < BH; j++) {
  const sy = (j/BH - .5)*(BH/BW)/zoom + P.y;
  for (let i = 0; i < BW; i++) {
    const p = j*BW + i;
    const sx = (i/BW - .5)/zoom + P.x;
    surf(sx, sy, SPa, aA);
    let h = OH, t = OT;
    if (diss > 0) {                                        // soft low-frequency re-etch, not a dither
      const m = cl((diss*1.5 - vn(i, j, 51, 13)*.55 - .12)*3, 0, 1);
      if (m > .002) { const hA = h, tA = t; surf(sx, sy, SPb, aB); h = hA + (OH - hA)*m; t = tA + (OT - tA)*m; }
