    const edge = slope*slope*slope*glare;                  // the SEM tell, now subordinate
    let v = TB[p]*(.30 + .70*lam)*gain + edge;
    v *= .90 + .13*(.5 + .5*Math.sin((i/BW)*2.2 + chg*6.2831));   // slow charging gradient
    v = Math.max(0, Math.min(.96, v));

    let r, gg, b;
    if (style === 'stereo') {                              // optical stereo scope: warm metal, shallow DOF
      const hh = hb/360;
