      const mud = .30;
      r = r*vg + mud*(1-vg)*.55; gg = gg*vg + mud*(1-vg)*.5; b = b*vg + mud*(1-vg)*.46;
    } else if (style === 'thermal') {                      // ironbow false colour
      const m = Math.min(1, v*.9);
