      b = Math.min(1, Math.max(0, m*3.0 - 2.0) + Math.max(0, .42 - m*1.6));
    } else if (style === 'contour') {                      // topographic abstraction: pure line on film
      const lv = Math.abs((HB[p]*42) % 1 - .5);
      const ln = lv < .06 ? 1 : 0;
      const maj = Math.abs((HB[p]*8.4) % 1 - .5) < .05 ? 1 : 0;
      const k2 = Math.min(1, ln*.60 + maj*.62);
